extern "C" int strcmp(const char *, const char *);
extern "C" void free(void *);

class nglFixedString
{
  char str[32];

public:
  typedef nglFixedString FS;

  bool operator==(const FS &rhs) const
  {
    for (int i = 0; i < 8; ++i)
      if (!(((const int *)str)[i] == ((const int *)rhs.str)[i]))
        return false;
    return true;
  }

  bool operator>=(const FS &rhs)
  {
    return strcmp(&str[0], &rhs.str[0]) >= 0;
  }
};

class nglInstanceBank
{
public:
  struct Instance
  {
    nglFixedString Key;
    void *Value;
    int RefCount;
    Instance *Forward[1];
  };

  typedef void (*InstanceFree)(void *);

  Instance *NIL;
  Instance *Head;

private:
  int RandomsLeft;
  int RandomBits;
  int Level;

public:
  static InstanceFree FreeFunc;
  int Delete(const nglFixedString &Key);
};

int nglInstanceBank::Delete(const nglFixedString &Key)
{
  int k, m;
  Instance *update[16];
  Instance *p;
  Instance *q;
  p = Head;
  k = m = Level;
  do
  {
    for (;;)
    {
      q = p->Forward[k];
      if (q->Key >= Key)
        break;
      p = q;
    }
    update[k] = p;
  }
  while (--k >= 0);
  if (q->Key == Key)
  {
    int RefCount = --q->RefCount;
    if (RefCount <= 0)
    {
      for (
        k = 0;
        k <= m && (p = update[k])->Forward[k] == q;
        k++)
        p->Forward[k] = q->Forward[k];

      if (FreeFunc)
      {
        FreeFunc(q);
      }
      else
      {
        free(q);
      }

      while (Head->Forward[m] == NIL && m > 0)
        m--;
      Level = m;
    }
    return RefCount;
  }
  else
    return -1;
}
